<script lang="ts">
	import type { PageData } from './$types';
	import { CreditCard, Download } from 'lucide-svelte';
	let { data }: { data: PageData } = $props();
	const totals = $derived(data.payments.reduce((acc, payment) => { if (payment.status === 'SUCCESS') acc.paid += Number(payment.amount); if (payment.status === 'REFUNDED') acc.refunded += Number(payment.amount); return acc; }, { paid: 0, refunded: 0 }));
</script>
<svelte:head><title>Payment management – Admin</title></svelte:head>
<main class="mx-auto max-w-6xl p-4 sm:p-6">
	<div class="mb-6 flex flex-wrap items-center justify-between gap-3"><div class="flex items-start gap-3"><span class="rounded-xl bg-emerald-100 p-3 text-emerald-700"><CreditCard size={22}/></span><div><h1 class="text-2xl font-bold text-gray-900">Payment management</h1><p class="mt-1 text-sm text-gray-500">Track payment attempts and refunds linked to orders.</p></div></div><a href="/admin/reports/payments.csv" class="inline-flex items-center gap-2 rounded-xl bg-emerald-700 px-4 py-2.5 text-sm font-semibold text-white"><Download size={16}/> Export CSV</a></div>
	<div class="mb-5 grid gap-3 sm:grid-cols-3"><div class="rounded-2xl bg-white p-4 shadow-sm"><div class="text-sm text-gray-500">Payment records</div><div class="mt-1 text-2xl font-bold">{data.payments.length}</div></div><div class="rounded-2xl bg-white p-4 shadow-sm"><div class="text-sm text-gray-500">Successful payments</div><div class="mt-1 text-2xl font-bold text-emerald-700">₹{totals.paid.toFixed(2)}</div></div><div class="rounded-2xl bg-white p-4 shadow-sm"><div class="text-sm text-gray-500">Refunded</div><div class="mt-1 text-2xl font-bold text-orange-700">₹{totals.refunded.toFixed(2)}</div></div></div>
	<div class="overflow-x-auto rounded-2xl border border-gray-100 bg-white"><table class="w-full min-w-[760px] text-left text-sm"><thead class="bg-gray-50 text-xs uppercase text-gray-500"><tr><th class="px-4 py-3">Order</th><th class="px-4 py-3">Customer</th><th class="px-4 py-3">Amount</th><th class="px-4 py-3">Method</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Reference / date</th></tr></thead><tbody class="divide-y divide-gray-100">{#each data.payments as p (p.id)}<tr><td class="px-4 py-3"><a class="font-semibold text-violet-700 hover:underline" href={p.orderId ? `/admin/orders/${p.orderId}` : '/admin/orders'}>{p.orderNumber ?? 'Order'}</a></td><td class="px-4 py-3">{p.customerName}</td><td class="px-4 py-3 font-semibold">{p.currency} {Number(p.amount).toFixed(2)}</td><td class="px-4 py-3">{p.method}</td><td class="px-4 py-3"><span class="rounded-full bg-gray-100 px-2 py-1 text-xs">{p.status}</span></td><td class="px-4 py-3 text-gray-500">{p.paymentReference ?? '—'}<div class="text-xs">{new Date(p.createdAt).toLocaleString('en-IN')}</div></td></tr>{/each}</tbody></table>{#if data.payments.length === 0}<p class="p-8 text-center text-sm text-gray-500">No payment records yet. COD orders may not create a payment record until collection.</p>{/if}</div>
</main>
